import{_ as t,c as e,o as i,V as r}from"./chunks/framework.GYYi-SO7.js";const p=JSON.parse('{"title":"nb05 · Embedding evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"research/embedding-evaluation.md","filePath":"research/embedding-evaluation.md"}'),d={name:"research/embedding-evaluation.md"},a=r('<h1 id="nb05-·-embedding-evaluation" tabindex="-1">nb05 · Embedding evaluation <a class="header-anchor" href="#nb05-·-embedding-evaluation" aria-label="Permalink to &quot;nb05 · Embedding evaluation&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb05_embedding_evaluation.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>Select the production embedding model for retrieval. The corpus is English-only, but a large share of production queries arrive in French, so cross-lingual retrieval (FR query → EN corpus) must be measured rather than assumed.</p><h2 id="evaluation-design" tabindex="-1">Evaluation design <a class="header-anchor" href="#evaluation-design" aria-label="Permalink to &quot;Evaluation design&quot;">​</a></h2><p>The corpus is 1,251 files / 9,893 chunks. The gold set is <strong>200 queries</strong>, each written in both English and French, across four layers that test different retrieval behaviours:</p><table><thead><tr><th>Layer</th><th>Query form</th><th>What it tests</th><th style="text-align:right;">Queries</th></tr></thead><tbody><tr><td><code>A_symbol</code></td><td>API / component name</td><td>exact identifier match</td><td style="text-align:right;">60</td></tr><tr><td><code>B_docs</code></td><td>natural-language question</td><td>semantic understanding</td><td style="text-align:right;">80</td></tr><tr><td><code>C_code</code></td><td>concept → file</td><td>cross-modal (NL → code)</td><td style="text-align:right;">45</td></tr><tr><td><code>negative</code></td><td>out-of-scope question</td><td>rejection</td><td style="text-align:right;">15</td></tr></tbody></table><p>The headline metric is <code>hit@5</code>; <code>hit@1</code>, <code>hit@10</code> and MRR are also recorded.</p><h2 id="candidate-models" tabindex="-1">Candidate models <a class="header-anchor" href="#candidate-models" aria-label="Permalink to &quot;Candidate models&quot;">​</a></h2><p>Three dense models were retained after dropping four from earlier runs (<code>e5-large</code> / <code>e5-large-instruct</code> — 512-token cap forces truncation; <code>nomic-v1.5</code> — English-only, fails on FR; <code>jina-code</code> — incompatible with the current <code>transformers</code> pin):</p><table><thead><tr><th>Model</th><th>Family</th><th style="text-align:right;">Context</th></tr></thead><tbody><tr><td><code>qwen3-0.6b</code> (<code>Qwen/Qwen3-Embedding-0.6B</code>)</td><td>multilingual + code-aware</td><td style="text-align:right;">8K</td></tr><tr><td><code>arctic-l-v2</code> (<code>Snowflake/snowflake-arctic-embed-l-v2.0</code>)</td><td>multilingual</td><td style="text-align:right;">8K</td></tr><tr><td><code>bge-m3</code> (<code>BAAI/bge-m3</code>)</td><td>multilingual</td><td style="text-align:right;">8K</td></tr></tbody></table><p>All three accept 8K tokens, so every chunk fits without truncation. All produce 1024-dim vectors.</p><h2 id="retrieval-configurations-compared" tabindex="-1">Retrieval configurations compared <a class="header-anchor" href="#retrieval-configurations-compared" aria-label="Permalink to &quot;Retrieval configurations compared&quot;">​</a></h2><p>Four configurations: each dense model alone; <strong>BM25</strong> (lexical baseline); <strong>hybrid</strong> (the leading dense model fused with BM25 via Reciprocal Rank Fusion, K=60 — selected from K ∈ {30, 60, 90}); and a <strong>cross-encoder reranker</strong> applied to the top-20 of the hybrid run, on the natural-language layers (<code>B_docs</code>, <code>C_code</code>) only.</p><p>BM25 alone scores well on <code>A_symbol</code> (en 0.850 / fr 0.833, since identifiers are literal tokens) but poorly elsewhere, particularly on FR (<code>B_docs</code> fr 0.100, <code>C_code</code> fr 0.089).</p><h2 id="results-—-hit-5-per-layer" tabindex="-1">Results — hit@5 per layer <a class="header-anchor" href="#results-—-hit-5-per-layer" aria-label="Permalink to &quot;Results — hit@5 per layer&quot;">​</a></h2><table><thead><tr><th>Approach</th><th style="text-align:right;">A_symbol</th><th style="text-align:right;">B_docs</th><th style="text-align:right;">C_code</th><th style="text-align:right;">negative</th></tr></thead><tbody><tr><td>qwen3-0.6b</td><td style="text-align:right;"><strong>0.883</strong></td><td style="text-align:right;"><strong>0.706</strong></td><td style="text-align:right;">0.633</td><td style="text-align:right;">0.000</td></tr><tr><td>arctic-l-v2</td><td style="text-align:right;">0.833</td><td style="text-align:right;">0.625</td><td style="text-align:right;">0.611</td><td style="text-align:right;">0.133</td></tr><tr><td>bge-m3</td><td style="text-align:right;">0.808</td><td style="text-align:right;">0.556</td><td style="text-align:right;">0.556</td><td style="text-align:right;">0.133</td></tr><tr><td>bm25</td><td style="text-align:right;">0.842</td><td style="text-align:right;">0.250</td><td style="text-align:right;">0.200</td><td style="text-align:right;">0.167</td></tr><tr><td>hybrid_k60</td><td style="text-align:right;">0.875</td><td style="text-align:right;">0.575</td><td style="text-align:right;">0.589</td><td style="text-align:right;">0.033</td></tr><tr><td>hybrid_k60 + rerank</td><td style="text-align:right;">0.875</td><td style="text-align:right;">0.594</td><td style="text-align:right;"><strong>0.656</strong></td><td style="text-align:right;">0.033</td></tr></tbody></table><p><code>qwen3-0.6b</code> is highest on <code>A_symbol</code> and <code>B_docs</code>; the reranked hybrid is highest on <code>C_code</code>. On the <code>negative</code> layer, <code>qwen3-0.6b</code> reaches 0.000 (it does not return out-of-scope sources), whereas the lexical and weaker dense models retain some false positives.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><table><thead><tr><th>Model</th><th style="text-align:right;">Chunks/sec</th><th style="text-align:right;">Query mean</th><th style="text-align:right;">Query p95</th><th style="text-align:right;">Index</th></tr></thead><tbody><tr><td>qwen3-0.6b</td><td style="text-align:right;">90.5</td><td style="text-align:right;">23.2 ms</td><td style="text-align:right;">24.3 ms</td><td style="text-align:right;">38.6 MB</td></tr><tr><td>arctic-l-v2</td><td style="text-align:right;">52.7</td><td style="text-align:right;">10.9 ms</td><td style="text-align:right;">11.0 ms</td><td style="text-align:right;">38.6 MB</td></tr><tr><td>bge-m3</td><td style="text-align:right;">52.9</td><td style="text-align:right;">11.2 ms</td><td style="text-align:right;">12.3 ms</td><td style="text-align:right;">38.6 MB</td></tr></tbody></table><p><code>qwen3-0.6b</code> has the highest indexing throughput; <code>arctic-l-v2</code> / <code>bge-m3</code> have lower query latency. Index size is equal (1024-dim).</p><h2 id="fr-first-decision" tabindex="-1">FR-first decision <a class="header-anchor" href="#fr-first-decision" aria-label="Permalink to &quot;FR-first decision&quot;">​</a></h2><p>Because production traffic is French-leaning, the decisive metric is FR <code>hit@5</code> on the natural-language layers (<code>B_docs</code> + <code>C_code</code>). A weighted score across FR <code>B+C</code>, FR <code>A</code>, EN <code>B+C</code> and FR rejection ranks the configurations:</p><table><thead><tr><th>Approach</th><th style="text-align:right;">Weighted score</th><th style="text-align:right;">FR B+C</th><th style="text-align:right;">FR A</th><th style="text-align:right;">EN B+C</th></tr></thead><tbody><tr><td>qwen3-0.6b</td><td style="text-align:right;"><strong>0.698</strong></td><td style="text-align:right;"><strong>0.624</strong></td><td style="text-align:right;">0.883</td><td style="text-align:right;">0.736</td></tr><tr><td>arctic-l-v2</td><td style="text-align:right;">0.648</td><td style="text-align:right;">0.592</td><td style="text-align:right;">0.817</td><td style="text-align:right;">0.648</td></tr><tr><td>hybrid_k60 + rerank</td><td style="text-align:right;">0.644</td><td style="text-align:right;">0.560</td><td style="text-align:right;">0.867</td><td style="text-align:right;">0.672</td></tr></tbody></table><p><strong>Selected: <code>qwen3-0.6b</code>.</strong> It has the highest weighted score, the best FR <code>B+C</code> retrieval, and the highest indexing throughput. <code>arctic-l-v2</code> is the closest alternative.</p><h2 id="cross-lingual-experiment-—-would-french-docs-close-the-fr→en-gap" tabindex="-1">Cross-lingual experiment — would French docs close the FR→EN gap? <a class="header-anchor" href="#cross-lingual-experiment-—-would-french-docs-close-the-fr→en-gap" aria-label="Permalink to &quot;Cross-lingual experiment — would French docs close the FR→EN gap?&quot;">​</a></h2><p>French queries trail English on the natural-language layers (on the leader, <code>B_docs</code> FR 0.688 vs EN 0.725; <code>C_code</code> FR 0.511 vs EN 0.756). The corpus is English-only, so every French query must bridge the FR↔EN gap. This experiment tests whether French documentation would recover that difference, using <code>kalisio/dok</code> — which ships parallel English (<code>docs/</code>) and human-translated French (<code>docs/fr/</code>) trees: 24 EN files mirroring 24 FR files (~264 KB). 45 natural-language gold queries (EN/FR pairs) were evaluated in four settings:</p><table><thead><tr><th>Setting</th><th>Corpus</th><th>Query</th><th>hit@5 (qwen3 / arctic / bge-m3)</th></tr></thead><tbody><tr><td>EN→EN</td><td>EN docs</td><td>EN</td><td>0.911 / 0.889 / 0.867</td></tr><tr><td>FR→EN</td><td>EN docs</td><td>FR</td><td>0.844 / 0.867 / 0.844</td></tr><tr><td>FR→FR</td><td>FR docs</td><td>FR</td><td>0.889 / 0.889 / 0.911</td></tr><tr><td>FR→bi</td><td>both</td><td>FR</td><td>0.889 / 0.867 / 0.889</td></tr></tbody></table><ul><li>The mean cross-lingual difference recovered by FR→FR is <strong>+0.045 hit@5</strong>; the residual gap of FR→FR to the EN→EN ceiling is <strong>+0.007</strong> (i.e. FR monolingual reaches the EN monolingual level).</li><li>By query category, lexical-anchor queries (shared proper nouns, URLs, version numbers) score 1.000 in every setting — there is no cross-lingual gap when the anchor token is identical across languages. The gap appears only on term-divergent and general-concept queries, and is small.</li><li>Bilingual indexing (FR→bi) is within ~0.02 of FR→FR — adding both languages to one index neither helps nor harms materially.</li></ul><p>The conclusion is that with parallel EN/FR content sharing anchors, the cross-lingual gap is approximately zero — so the FR shortfall in the main evaluation is not primarily an embedding limitation.</p><h2 id="closing-the-fr-gap-—-glossary-vs-llm-query-translation" tabindex="-1">Closing the FR gap — glossary vs LLM query translation <a class="header-anchor" href="#closing-the-fr-gap-—-glossary-vs-llm-query-translation" aria-label="Permalink to &quot;Closing the FR gap — glossary vs LLM query translation&quot;">​</a></h2><p>A per-query error analysis on the main FR results separates failures by whether the FR query contains an English identifier anchor:</p><table><thead><tr><th>FR query carries an EN identifier?</th><th style="text-align:right;">n</th><th style="text-align:right;">FR-loss rate</th></tr></thead><tbody><tr><td>Yes (<code>composant KChart</code>, <code>activité MapActivity</code>)</td><td style="text-align:right;">114</td><td style="text-align:right;">10.5%</td></tr><tr><td>No (concept paraphrased, no project term)</td><td style="text-align:right;">71</td><td style="text-align:right;">32.4%</td></tr></tbody></table><p>The shortfall concentrates in code targets (<code>.vue</code> 36%, <code>.js</code> 27%) and the <code>C_code</code> layer. Project identifiers such as <code>mailer</code>, <code>EventLog</code>, <code>MapActivity</code> exist only in English; a multilingual embedding maps <code>envoi d&#39;emails</code> ≈ <code>email sending</code> but not ≈ <code>mailer</code>, which is project naming rather than standard English. The FR shortfall is therefore a terminology-coverage problem, not an embedding problem.</p><p>Two query-side approaches were compared against the original FR query: a hand-curated <strong>glossary</strong> (~25 FR-concept → EN-project-term entries, appended in parentheses, not substituted) and <strong>LLM query translation</strong>. Results (hit@5, positive queries):</p><table><thead><tr><th>Model</th><th style="text-align:right;">EN_orig</th><th style="text-align:right;">FR_orig</th><th style="text-align:right;">FR_glossary</th><th style="text-align:right;">Δ glossary</th></tr></thead><tbody><tr><td>qwen3-0.6b</td><td style="text-align:right;">0.784</td><td style="text-align:right;">0.708</td><td style="text-align:right;"><strong>0.811</strong></td><td style="text-align:right;">+0.103</td></tr><tr><td>arctic-l-v2</td><td style="text-align:right;">0.714</td><td style="text-align:right;">0.665</td><td style="text-align:right;">0.719</td><td style="text-align:right;">+0.054</td></tr><tr><td>bge-m3</td><td style="text-align:right;">0.659</td><td style="text-align:right;">0.616</td><td style="text-align:right;">0.692</td><td style="text-align:right;">+0.076</td></tr></tbody></table><p>The glossary raises FR <code>hit@5</code> above the EN baseline on <code>qwen3-0.6b</code> (0.708 → 0.811 vs EN 0.784). The gain is largest on <code>C_code</code> (FR 0.526 → 0.726, +0.200), the layer most dependent on project identifiers. The LLM-translation path could not be measured in this run (the local Ollama endpoint was unreachable and entries fell back to the original FR query), so its effect is not reported.</p><h2 id="selected-configuration" tabindex="-1">Selected configuration <a class="header-anchor" href="#selected-configuration" aria-label="Permalink to &quot;Selected configuration&quot;">​</a></h2><ul><li><strong>Embedding model: <code>qwen3-0.6b</code></strong> (<code>Qwen/Qwen3-Embedding-0.6B</code>).</li><li><strong>FR queries: glossary augmentation</strong> — a deterministic FR-concept → EN-project-term glossary appended to the query, which recovers the FR shortfall on code-identifier queries.</li><li><code>arctic-l-v2</code> and <code>bge-m3</code> are the multilingual baselines; <code>arctic-l-v2</code> is the closest alternative if a lower query latency is required.</li></ul><p>The selected model is used at index and query time — see <a href="/knowledge/architecture/rag.html">RAG: indexing &amp; retrieval</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Gold queries are authored from and evaluated on the same corpus, so <code>hit@k</code> measures within-corpus retrieval, not generalization. The main gold set is 200 queries; the cross-lingual and augmentation sets are 45 and 200.</li><li>The LLM query-translation path was not measured (the local model endpoint was unavailable); only the deterministic glossary path has measured results.</li><li>The cross-lingual experiment uses one parallel corpus (<code>dok</code>, ~264 KB of user docs); it does not cover API-reference or source-code content.</li><li>The glossary is hand-curated (~25 entries) and specific to the current corpus; new project-specific terms require new entries.</li></ul>',42),o=[a];function n(l,s,h,c,g,u){return i(),e("div",null,o)}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
